import{_ as a,a as i,b as o,c as r,d as t,e as n,f as s,g as l}from"./chunks/Install22b.DDLege5l.js";import{_ as p}from"./chunks/Install17.CwCXrGHM.js";import{_ as d,o as c,c as h,a3 as u}from"./chunks/framework.g9mfNVRQ.js";const q=JSON.parse('{"title":"Installazione","description":"","frontmatter":{"source_hash":"92fd90f109","source_commit":"7a18e7c"},"headers":[],"relativePath":"it/troubleshoot/install.md","filePath":"it/troubleshoot/install.md"}'),m={name:"it/troubleshoot/install.md"};function f(g,e,b,v,_,x){return c(),h("div",null,[...e[0]||(e[0]=[u('<h2 id="my-phone-says-this-app-is-very-dangerous" tabindex="-1">Il mio telefono dice che questa app è molto pericolosa <a class="header-anchor" href="#my-phone-says-this-app-is-very-dangerous" aria-label="Permalink to &quot;Il mio telefono dice che questa app è molto pericolosa {#my-phone-says-this-app-is-very-dangerous}&quot;">​</a></h2><p>Le release GitHub del <a href="https://github.com/NightscoutFoundation/xDrip/releases" target="_blank" rel="noreferrer">repository ufficiale</a> sono sicure. Ignora questo messaggio.</p><img src="'+a+'" style="zoom:75%;"><br><h2 id="i-cannot-find-the-file-i-downloaded" tabindex="-1">Non trovo il file che ho scaricato <a class="header-anchor" href="#i-cannot-find-the-file-i-downloaded" aria-label="Permalink to &quot;Non trovo il file che ho scaricato {#i-cannot-find-the-file-i-downloaded}&quot;">​</a></h2><p>Apri un file manager e guarda nella cartella Download della memoria interna del telefono: dovresti vedere un file con un nome simile a <code>xDrip-plus-20yymmdd-cccccccc.apk</code></p><br><h2 id="when-i-touch-the-xdrip-apk-it-opens-a-file-list" tabindex="-1">Quando tocco il file .apk di xDrip si apre un elenco di file <a class="header-anchor" href="#when-i-touch-the-xdrip-apk-it-opens-a-file-list" aria-label="Permalink to &quot;Quando tocco il file .apk di xDrip si apre un elenco di file {#when-i-touch-the-xdrip-apk-it-opens-a-file-list}&quot;">​</a></h2><p>Se il file xDrip-plus termina con .zip, rinominalo in .apk e riprova.</p><p>Se non c&#39;è modo di aprirlo con il programma di installazione dei pacchetti, prova con un <a href="https://play.google.com/store/apps/details?id=com.apkinstaller.ApkInstaller" target="_blank" rel="noreferrer">APK installer</a>.</p><br><h2 id="i-cannot-install-unknown-apps" tabindex="-1">Non riesco a installare app sconosciute <a class="header-anchor" href="#i-cannot-install-unknown-apps" aria-label="Permalink to &quot;Non riesco a installare app sconosciute {#i-cannot-install-unknown-apps}&quot;">​</a></h2><img src="'+i+'" style="zoom:75%;"><p>In Impostazioni Android -&gt; <a href="https://developer.android.com/distribute/marketing-tools/alternative-distribution#unknown-sources" target="_blank" rel="noreferrer">Impostazioni di sicurezza</a> devi consentire all&#39;app che usi per aprire il file scaricato di installare file da origini sconosciute; se disponibile, seleziona solo questa volta.</p><p>Qui sotto l&#39;esempio per Chrome; tu potresti usare un&#39;altra app per aprire il file .apk di xDrip.</p><img src="'+o+'" style="zoom:75%;"><br><h2 id="i-cannot-install-the-app" tabindex="-1">Non riesco a installare l&#39;app <a class="header-anchor" href="#i-cannot-install-the-app" aria-label="Permalink to &quot;Non riesco a installare l&#39;app {#i-cannot-install-the-app}&quot;">​</a></h2><img src="'+r+'" style="zoom:75%;"><p>Assicurati di non avere installata una versione diversa di xDrip: puoi aggiornare o riportare a una versione precedente solo app dello stesso sviluppatore. Se necessario, <a href="./reinstall.html">reinstalla</a> xDrip per passare dalla versione ufficiale a una versione fork (e viceversa).</p><br><h2 id="my-phone-says-this-app-is-unsafe-and-has-been-built-for-an-older-android-version" tabindex="-1"><strong>Il mio telefono dice che questa app non è sicura ed è stata creata per una versione di Android precedente</strong> <a class="header-anchor" href="#my-phone-says-this-app-is-unsafe-and-has-been-built-for-an-older-android-version" aria-label="Permalink to &quot;**Il mio telefono dice che questa app non è sicura ed è stata creata per una versione di Android precedente** {#my-phone-says-this-app-is-unsafe-and-has-been-built-for-an-older-android-version}&quot;">​</a></h2><p>Ignoralo con Altri dettagli, poi Installa comunque.</p><img src="'+t+'" style="zoom:75%;"><br><h2 id="xdrip-needs-background-location" tabindex="-1">xDrip ha bisogno della posizione in background <a class="header-anchor" href="#xdrip-needs-background-location" aria-label="Permalink to &quot;xDrip ha bisogno della posizione in background {#xdrip-needs-background-location}&quot;">​</a></h2><img src="'+n+'" style="zoom:60%;"><p>Se vuoi che xDrip si colleghi a un dispositivo Bluetooth, deve avere l&#39;<a href="./../install/install.html#enable-location">accesso alla posizione</a> permanente.</p><p>Nelle versioni di Android più recenti vai in Impostazioni Android -&gt; Posizione -&gt; App -&gt; xDrip oppure Impostazioni Android -&gt; App -&gt; xDrip -&gt; Posizione e verifica che sia attivo Consenti sempre.</p><img src="'+p+'" style="zoom:80%;"><br><h2 id="xdrip-needs-battery-optimization-whitelisting" tabindex="-1">xDrip deve essere escluso dall&#39;ottimizzazione della batteria <a class="header-anchor" href="#xdrip-needs-battery-optimization-whitelisting" aria-label="Permalink to &quot;xDrip deve essere escluso dall&#39;ottimizzazione della batteria {#xdrip-needs-battery-optimization-whitelisting}&quot;">​</a></h2><img src="'+s+'" style="zoom:60%;"><p>xDrip non deve essere ottimizzato in alcun modo.</p><p>La posizione di questa impostazione varia a seconda della marca e della versione di Android; di solito la trovi in Impostazioni Android -&gt; App -&gt; xDrip -&gt; Batteria</p><img src="'+l+'" style="zoom:100%;"><p>Potrebbe essere necessario riavviare il telefono per applicare queste modifiche. Se il messaggio di avviso resta, assicurati di usare una versione recente di xDrip: aggiornala se necessario.</p><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2022.03.27" target="_blank" rel="noreferrer"><em>Ultima modifica 28/3/2022</em></a></p>',39)])])}const D=d(m,[["render",f]]);export{q as __pageData,D as default};
